def _world_adventures_editor_payload():
    """Conteúdo do editor do mapa-múndi; mantém a lista de dungeons confiável."""
    return {
        "locations": [dict(loc) for loc in WORLD_LOCATIONS.values()],
        "adventures": list(WORLD_ADVENTURES.values()),
        "dungeons": listar_dungeons(),
        "map_image": "assets/city/varluzia - Copia.png",
    }

def _clean_requirement(raw):
    """Normaliza a trava comum de conversas e destinos.

    Todos os campos são opcionais e se acumulam (AND). Assim o editor não
    precisa criar uma regra nova a cada combinação narrativa.
    """
    raw = raw if isinstance(raw, dict) else {}
    def text(key): return str(raw.get(key) or "").strip()[:100]
    try: renome = max(0, min(9999, int(raw.get("renome_min", 0))))
    except (TypeError, ValueError): renome = 0
    try: nivel = max(0, min(99, int(raw.get("nivel_grupo_min", 0))))
    except (TypeError, ValueError): nivel = 0
    return {"renome_min": renome, "nivel_grupo_min": nivel,
            "item_id": text("item_id"), "fato": text("fato"),
            "aventura_id": text("aventura_id")}

def _save_world_adventures_upload(raw_locations, raw_adventures):
    """Valida e grava cidades e entradas de aventura criadas no editor."""
    global WORLD_ADVENTURES
    if not isinstance(raw_locations, list) or not isinstance(raw_adventures, list):
        return False, "Dados do mapa inválidos."
    for loc in raw_locations:
        if not isinstance(loc, dict) or loc.get("id") not in WORLD_LOCATIONS:
            continue
        try:
            x, y = round(float(loc["x"]), 2), round(float(loc["y"]), 2)
        except (KeyError, TypeError, ValueError):
            continue
        if 0 <= x <= 100 and 0 <= y <= 100:
            WORLD_LOCATIONS[loc["id"]]["x"] = x
            WORLD_LOCATIONS[loc["id"]]["y"] = y

    allowed_files = {entry.get("file") for entry in listar_dungeons() if entry.get("file")}
    cleaned = {}
    for row in raw_adventures[:80]:
        if not isinstance(row, dict):
            continue
        aid = str(row.get("id") or "").strip().lower()
        name = str(row.get("nome") or "").strip()
        if not re.fullmatch(r"[a-z0-9_-]{1,48}", aid) or not name or aid in cleaned:
            continue
        try:
            x, y = round(float(row["x"]), 2), round(float(row["y"]), 2)
            fome, sede = max(0, int(row.get("fome", 0))), max(0, int(row.get("sede", 0)))
        except (KeyError, TypeError, ValueError):
            continue
        if not (0 <= x <= 100 and 0 <= y <= 100):
            continue
        files = row.get("dungeons", [])
        if not isinstance(files, list): files = []
        etapas = []
        for raw_stage in files[:20]:
            et = _etapa_obj(raw_stage)
            if et["file"] in allowed_files:
                etapa = {"file": et["file"], "encadear": et["encadear"],
                         "intro": _clean_story_field(et["intro"]),
                         "outro": _clean_story_field(et["outro"])}
                trigger = _clean_location_scene_trigger(et.get("scene_trigger"))
                if trigger:
                    etapa["scene_trigger"] = trigger
                etapas.append(etapa)
        # Um destino recém-criado pode ser salvo antes de receber a primeira
        # masmorra. Preservamos esse rascunho para o editor, mas ele não aparece
        # para os jogadores até ficar jogável (ver _aventura_visivel).
        req = _clean_requirement(row.get("requisito"))
        try: renome_reward = max(0, min(9999, int(row.get("renome_recompensa", 1))))
        except (TypeError, ValueError): renome_reward = 1
        cleaned[aid] = {"id": aid, "nome": name[:80], "x": x, "y": y,
                        "fome": fome, "sede": sede, "dungeons": etapas,
                        "espera_retorno": _clean_espera(row.get("espera_retorno")),
                        "oculto_ate_liberar": bool(row.get("oculto_ate_liberar")),
                        "revisitavel": bool(row.get("revisitavel")),
                        "outro_rota": _clean_story_field(row.get("outro_rota")),
                        "requisito": req, "renome_recompensa": renome_reward}
    try:
        WORLD_ADVENTURES = cleaned
        _save_world_map_points(); _save_world_adventures()
    except OSError:
        return False, "Não foi possível salvar o mapa-múndi."
    return True, _world_adventures_editor_payload()

