# â”€â”€â”€ D20 HELPERS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

def mod(score): return (score - 10) // 2

def monster_default_perception(monster):
    """Percepção base para fichas legadas sem campo explícito."""
    base = int(monster.get("movement", 6)) if monster.get("movement_exception") else 6
    vision_base = max(-30, min(30, int(monster.get("vision_base", 0) or 0)))
    dex_mod = mod(int(monster.get("dex", 10) or 10))
    int_mod = mod(int(monster.get("int_", 10) or 10))
    two_heads = any(a.get("id") == "duas_cabecas"
                    for a in (monster.get("special_abilities") or [])
                    if isinstance(a, dict))
    vision = max(1, base + vision_base + (dex_mod + int_mod) // 2
                 + (2 if two_heads else 0))
    return max(1, 10 + vision // 2)

def get_bonus_constituicao(constituicao):
    """Bônus de HP/Fortitude baseado na Constituição (tabela D20 expandida 0–25)."""
    tabela = {
         0: -5,  1: -5,  2: -4,  3: -4,  4: -3,  5: -3,
         6: -2,  7: -2,  8: -1,  9: -1, 10:  0, 11:  0,
        12: +1, 13: +1, 14: +2, 15: +2, 16: +3, 17: +3,
        18: +4, 19: +4, 20: +5, 21: +5, 22: +6, 23: +6,
        24: +7, 25: +7,
    }
    valor_seguro = max(0, min(25, int(constituicao)))
    return tabela[valor_seguro]

# Sobrevivência separa o teto permanente dos modificadores temporários. Assim,
# efeitos futuros (por exemplo, veneno) podem reduzir o máximo por algumas
# rodadas sem destruir a progressão permanente obtida nos níveis.
def _max_sobrevivencia(player, recurso):
    base = int(player.get(f"{recurso}_max_base", player.get(f"{recurso}_max", 100)))
    mods = player.get(f"{recurso}_max_modificadores", [])
    delta = sum(int(m.get("valor", 0)) for m in mods if isinstance(m, dict))
    return max(0, base + delta)

def _recalcular_maximos_sobrevivencia(player):
    for recurso in ("fome", "sede"):
        teto = _max_sobrevivencia(player, recurso)
        player[f"{recurso}_max"] = teto
        player[recurso] = min(teto, max(0, int(player.get(recurso, teto))))

def _restaurar_sobrevivencia(player, fome=0, sede=0):
    _recalcular_maximos_sobrevivencia(player)
    player["fome"] = min(player["fome_max"], player.get("fome", 0) + fome)
    player["sede"] = min(player["sede_max"], player.get("sede", 0) + sede)

def roll_dice(die_str):
    """Rola uma expressão de dados com múltiplos termos somados/subtraídos —
    cada termo é 'NdM' (rolagem) ou 'K' (constante).
    Ex.: '1d8', '2d6+3', '2d6+1d4-1', '1d6-2'."""
    s = str(die_str).strip().replace(' ', '')
    if not s:
        return 0
    total, i, n, sinal = 0, 0, len(s), 1
    while i < n:
        if s[i] in '+-':
            sinal = -1 if s[i] == '-' else 1
            i += 1
        j = i
        while j < n and s[j] not in '+-':
            j += 1
        termo, i = s[i:j], j
        if not termo:
            continue
        if 'd' in termo:
            a, _, b = termo.partition('d')
            cnt = int(a) if a else 1
            total += sinal * sum(random.randint(1, int(b)) for _ in range(cnt))
        else:
            total += sinal * int(termo)
        sinal = 1
    return total

def _ndfaces(die_str):
    """'2d6' -> (2, 6); '1' -> (1, 1) (dano fixo de 1 ponto)."""
    if "d" not in die_str:
        return (int(die_str), 1)
    n, faces = die_str.split("d")
    return (int(n or 1), int(faces))

def d20_attack(atk_bonus, target_ac):
    """Roll 1d20+atk_bonus vs target_ac. Returns (hit, roll, total, crit)."""
    roll = random.randint(1, 20)
    total = roll + atk_bonus
    crit = (roll == 20)
    return (crit or total >= target_ac), roll, total, crit

