_QUALIDADE_LABEL = {
    "velho": ("Velho", "Velha"), "rustico": ("Rústico", "Rústica"),
    "padrao": ("Padrão", "Padrão"), "refinado": ("Refinado", "Refinada"),
}
_INSTRUMENTO_GENERO_FEM = {"harpa", "trompa", "lira", "flauta", "gaita"}
_ORIGEM_LABEL = {          # (masculino, feminino)
    "elfica": ("Élfico", "Élfica"),
    "ana":    ("Anão", "Anã"),
}
_RUNICO_LABEL   = ("Rúnico", "Rúnica")      # (masc, fem) â€” Encantamento RÃºnico (Fase 4b)
_LENDARIO_LABEL = ("Lendário", "Lendária")  # (masc, fem) â€” 3 eixos no mÃ¡ximo

_ORIGEM_AFIXOS = {
    "elfica": ["cd", "alcance", "duracao"],
    "ana":    ["fome_sede", "duracao", "concentracao"],
}

def _afixo_aplicavel(base, bonus):
    """True se o afixo faz efeito neste instrumento (evita origem sem bônus)."""
    b = INSTRUMENTOS_BASE[base]
    stp = b["stats"]["padrao"]
    if bonus == "fome_sede":
        return True
    if bonus == "cd":
        return bool(b["efeito"].get("save"))
    if bonus == "alcance":
        return any(k in stp for k in ("alcance", "raio", "cone"))
    if bonus == "duracao":
        return "duracao" in stp
    if bonus == "concentracao":
        return b["efeito"].get("tipo") == "requiem_final"
    return False

def _afixos_validos_origem(base, origem):
    """Pool de afixos da origem ∩ aplicáveis à base."""
    return [a for a in _ORIGEM_AFIXOS.get(origem, []) if _afixo_aplicavel(base, a)]

def criar_instrumento(base, qualidade="padrao", origem="humana", encantamento="nenhum",
                      refinado_bonus=None, origem_bonus=None):
    """Cria uma instância de instrumento (item de bolsa/gear)."""
    b = INSTRUMENTOS_BASE[base]
    inst = {
        "id": "instrumento", "tipo_item": "instrumento",
        "base": base, "qualidade": qualidade,
        "origem": origem, "encantamento": encantamento,
        "refinado_bonus": refinado_bonus if qualidade == "refinado" else None,
        "origem_bonus": origem_bonus if origem in ("elfica", "ana") else None,
        "emoji": b["icon"], "item_slot": "instrumento",
        "allowed_classes": ["bard"],
    }
    inst["name"] = _instrumento_nome(inst)
    return inst

def instrumento_sku(base, qualidade="padrao", preco=100, refinado_bonus=None,
                    origem="humana", origem_bonus=None, encantamento="nenhum"):
    """Instância de instrumento para a loja/loot (id único + price/buy_price).
    Origem ≠ Humana e Rúnico entram no id para não colidir (Fase 4a/4b)."""
    inst = criar_instrumento(base, qualidade, origem=origem, encantamento=encantamento,
                             refinado_bonus=refinado_bonus, origem_bonus=origem_bonus)
    suf = f"_{origem}" if origem in ("elfica", "ana") else ""
    if encantamento == "runico":
        suf += "_runico"
    inst["id"] = f"instrumento_{base}_{qualidade}{suf}"
    inst["price"] = preco       # lido por handle_shop_buy (item["price"]) no catÃ¡logo
    inst["buy_price"] = preco   # gravado na instÃ¢ncia adquirida (revenda)
    return inst

# â”€â”€â”€ Roller procedural de instrumentos (Fase 4a) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
_ROLLER_BASES = ["harpa", "tambor", "sino", "alaude", "trompa", "lira", "flauta", "violino", "gaita"]
_ROLLER_QUALIDADES = [("velho", 35), ("rustico", 30), ("padrao", 25), ("refinado", 10)]
_ROLLER_ORIGENS = [("humana", 70), ("elfica", 15), ("ana", 15)]

def _weighted_choice(pairs):
    total = sum(w for _, w in pairs)
    r = random.uniform(0, total)
    acc = 0.0
    for val, w in pairs:
        acc += w
        if r <= acc:
            return val
    return pairs[-1][0]

def gerar_instrumento_aleatorio(bases=None):
    """Instrumento procedural ponderado (base × qualidade × origem), com afixos
    pré-rolados válidos. Élfica sem afixo aplicável (Alaúde) rebaixa p/ Humana."""
    base = random.choice(bases or _ROLLER_BASES)
    qualidade = _weighted_choice(_ROLLER_QUALIDADES)
    origem = _weighted_choice(_ROLLER_ORIGENS)
    origem_bonus = None
    if origem in ("elfica", "ana"):
        validos = _afixos_validos_origem(base, origem)
        if validos:
            origem_bonus = random.choice(validos)
        else:
            origem = "humana"
    refinado_bonus = None
    if qualidade == "refinado":
        afx = INSTRUMENTOS_BASE[base].get("afixos_validos", [])
        if afx:
            refinado_bonus = random.choice(afx)
    encantamento = "runico" if random.random() < 0.04 else "nenhum"   # RÃºnico rarÃ­ssimo (Fase 4b)
    return criar_instrumento(base, qualidade, origem, encantamento, refinado_bonus, origem_bonus)

def _resolver_loot_instrumento(entry):
    """Token de loot procedural: {"tipo":"instrumento_aleatorio"} → instância; senão None."""
    if isinstance(entry, dict) and entry.get("tipo") == "instrumento_aleatorio":
        return gerar_instrumento_aleatorio()
    return None

def _instrumento_nome(inst):
    b = INSTRUMENTOS_BASE[inst["base"]]
    fem = inst["base"] in _INSTRUMENTO_GENERO_FEM
    orig = inst.get("origem", "humana")
    runico = inst.get("encantamento") == "runico"
    # LendÃ¡rio: 3 eixos no mÃ¡ximo (Refinado + Origem â‰  Humana + RÃºnico) â†’ "LendÃ¡ria/o"
    # substitui a qualidade e o sufixo RÃºnico; a origem permanece.
    if inst.get("qualidade") == "refinado" and orig in _ORIGEM_LABEL and runico:
        return f"{b['nome']} {_LENDARIO_LABEL[1 if fem else 0]} {_ORIGEM_LABEL[orig][1 if fem else 0]}"
    ql = _QUALIDADE_LABEL.get(inst["qualidade"], ("Padrão", "Padrão"))[1 if fem else 0]
    nome = f"{b['nome']} {ql}"
    if orig in _ORIGEM_LABEL:
        nome += " " + _ORIGEM_LABEL[orig][1 if fem else 0]
    if runico:
        nome += " " + _RUNICO_LABEL[1 if fem else 0]
    return nome

def _instrumento_nome_T(inst):
    """Irmã TARDIA de `_instrumento_nome`: mesmas regras, mas devolve um T para a
    frase ser montada no idioma de quem lê.

    `_instrumento_nome` continua devolvendo português puro — é ela que grava
    `inst["name"]`, e isso vai a disco no savegame. Esta aqui só entra na
    narração.

    A ORDEM das partes é do template (`cat.instrumento.nome_composto`), porque em
    inglês o adjetivo vem ANTES do substantivo; e o espaço vem embutido em cada
    adjetivo, no lado certo de cada idioma (" Velha" × "Old "), que é o que faz
    uma parte ausente não deixar espaço solto. O gênero só existe no `pt`.

    Gêmea do `_instrumentoComposto` em `src/i18n.js`, que lê as MESMAS chaves —
    o instrumento tem id único por combinação e não existe em catálogo nenhum."""
    b = INSTRUMENTOS_BASE[inst["base"]]
    g = "f" if inst["base"] in _INSTRUMENTO_GENERO_FEM else "m"
    orig = inst.get("origem", "humana")
    runico = inst.get("encantamento") == "runico"
    base = nome_cat("instrumento", inst["base"], b["nome"])
    adj = lambda nome: T(f"cat.instrumento.adj.{nome}.{g}")
    # Lendário: 3 eixos no máximo (Refinado + Origem ≠ Humana + Rúnico) →
    # substitui a qualidade E o sufixo Rúnico; a origem permanece.
    if inst.get("qualidade") == "refinado" and orig in _ORIGEM_LABEL and runico:
        return T("cat.instrumento.nome_composto", base=base, ql=adj("lendario"),
                 orig=adj(orig), run="")
    return T("cat.instrumento.nome_composto", base=base,
             ql=adj(inst.get("qualidade") if inst.get("qualidade") in _QUALIDADE_LABEL
                    else "padrao"),
             orig=adj(orig) if orig in _ORIGEM_LABEL else "",
             run=adj("runico") if runico else "")

def _distancia_chebyshev(pos1, pos2):
    """Distância de rei (Chebyshev) entre dois pontos [x, y]."""
    return max(abs(pos1[0] - pos2[0]), abs(pos1[1] - pos2[1]))

