def guild_item(item_id):
    return GUILD_CATALOG.get(item_id)

def _guild_classe_ok(item_classe, class_id):
    """True se `item_classe` (None, 1 class_id, ou lista/tupla de class_ids) libera `class_id`."""
    if item_classe is None:
        return True
    if isinstance(item_classe, (list, tuple, set)):
        return class_id in item_classe
    return item_classe == class_id

def guild_items_for_class(class_id):
    """Itens do catálogo disponíveis para uma classe (cópias para envio)."""
    return [dict(v) for v in GUILD_CATALOG.values() if _guild_classe_ok(v["classe"], class_id)]

def _habilidades_concedidas(player):
    """Ids de `granted_ability` dos itens EQUIPADOS (Fase I). Varre todos os slots
    de gear: hoje só arma/armadura/escudo/anel/bota carregam o campo, mas assim
    elmo/acessórios futuros funcionam sem mexer aqui."""
    out = set()
    for peca in (player.get("gear") or {}).values():
        if isinstance(peca, dict):
            aid = peca.get("granted_ability")
            if aid:
                out.add(aid)
    return out

def _pode_hab_heroi(player, cls_id, aid):
    """True se o jogador é da classe dona da habilidade OU se um item equipado a
    concede (Fase I/J). Portão único de todas as habilidades de herói concedíveis."""
    return player.get("class_id") == cls_id or aid in _habilidades_concedidas(player)

def _tem_alguma_hab_heroi(player, cls_id, aids):
    """True se o jogador é da classe OU tem qualquer um dos ids concedidos. Usado
    pelos upkeeps, que cobrem várias habilidades sustentadas de uma vez."""
    if player.get("class_id") == cls_id:
        return True
    return bool(set(aids) & _habilidades_concedidas(player))

def tem_espec(player, espec_id):
    """True se o jogador possui a especialização comprada (Fase 1+) OU se um item
    equipado a concede (Fase I)."""
    if espec_id in player.get("guild_owned", {}).get("especializacoes", []):
        return True
    return f"guild_{espec_id}" in _habilidades_concedidas(player)

def tem_tecnica_equipada(player, tecnica_id):
    """True se a técnica está no 4º slot equipado do jogador (normal ou exclusiva)
    OU se um item equipado a concede (Fase I)."""
    eq = player.get("guild_equip", {})
    if tecnica_id in (list(eq.get("tecnicas", [])) + [eq.get("tecnica"), eq.get("tecnica_exclusiva")]):
        return True
    return f"guild_{tecnica_id}" in _habilidades_concedidas(player)

def _quantidade_slots_guilda(player):
    """Um slot no nível 1, mais um nos níveis 5, 10, 15..."""
    return 1 + max(0, int(player.get("level", 1)) // 5)

def _garantir_slots_guilda(player):
    eq = player.setdefault("guild_equip", {})
    slots = eq.get("tecnicas")
    if not isinstance(slots, list):
        slots = [eq.get("tecnica")]
    slots = list(slots[:_quantidade_slots_guilda(player)])
    if slots and slots[0] is None and eq.get("tecnica"):
        slots[0] = eq["tecnica"]
    slots.extend([None] * (_quantidade_slots_guilda(player) - len(slots)))
    eq.clear()
    eq["tecnicas"] = slots
    # Campos de leitura legados: mantêm saves/testes antigos estáveis, mas a
    # fonte autoritativa de slots é sempre a lista `tecnicas`.
    eq["tecnica"] = slots[0] if slots else None
    eq["tecnica_exclusiva"] = None
    return slots

def _indice_slot_guilda(slot):
    if isinstance(slot, int):
        return slot
    if slot == "tecnica":
        return 0
    if isinstance(slot, str) and slot.startswith("tecnica_"):
        try:
            return int(slot.split("_", 1)[1])
        except ValueError:
            return None
    return None

# Ganhos a cada nível. saves_2 entra nos níveis 3,5,7... e saves_3 nos
# níveis 4,7,10...; no 7 ambos os grupos são aplicados.
