# â”€â”€â”€ MASMORRAS AUTORADAS (Fase 1 do editor) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
DUNGEONS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "dungeons")
# CatÃ¡logo de itens que um baÃº autorado pode conter (Fase 1: sÃ³ CHEST_ITEMS).
_DUNGEON_ITEM_CATALOG = {it["id"]: it for it in CHEST_ITEMS}

def _contar_chao_alcancavel(tiles, w, h, start, limite):
    """Conta casas caminháveis (FLOOR/DOOR) alcançáveis a partir de `start`,
    parando ao atingir `limite` (otimização). Usado p/ garantir spawn dos heróis."""
    sx, sy = start
    if not (0 <= sx < w and 0 <= sy < h) or tiles[sy][sx] == WALL:
        return 0
    visto = {(sx, sy)}; pilha = [(sx, sy)]; conta = 0
    while pilha:
        x, y = pilha.pop()
        conta += 1
        if conta >= limite:
            return conta
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if (0 <= nx < w and 0 <= ny < h and (nx, ny) not in visto
                    and tiles[ny][nx] != WALL):
                visto.add((nx, ny)); pilha.append((nx, ny))
    return conta

def validar_dungeon(defn):
    """Valida um dict de masmorra autorada. Retorna (ok: bool, msg: str)."""
    if not isinstance(defn, dict):
        return False, "Masmorra não é um objeto JSON."
    if defn.get("schema_version") != 1:
        return False, f"schema_version não suportado: {defn.get('schema_version')!r} (esperado 1)."
    grid = defn.get("grid")
    if not isinstance(grid, dict):
        return False, "grid ausente ou inválido."
    w, h = grid.get("w"), grid.get("h")
    if (isinstance(w, bool) or isinstance(h, bool)
            or not (isinstance(w, int) and isinstance(h, int)
                    and 1 <= w <= 60 and 1 <= h <= 60)):
        return False, "grid.w/grid.h ausentes ou fora de 1..60."
    tiles = defn.get("tiles")
    if not (isinstance(tiles, list) and len(tiles) == h):
        return False, f"tiles deve ter {h} linhas (grid.h)."
    for y, row in enumerate(tiles):
        if not (isinstance(row, list) and len(row) == w):
            return False, f"linha {y} de tiles deve ter {w} colunas (grid.w)."
        for x, v in enumerate(row):
            if v not in (0, 1, 2):
                return False, f"tile inválido em ({x},{y}): {v!r} (use 0/1/2)."

    def in_grid(p):
        return (isinstance(p, (list, tuple)) and len(p) == 2
                and isinstance(p[0], int) and isinstance(p[1], int)
                and 0 <= p[0] < w and 0 <= p[1] < h)

    def tile_at(p):
        return tiles[p[1]][p[0]]

    start_mode = defn.get("start_mode", "entrance")
    if start_mode not in ("entrance", "hero_spawns"):
        return False, "start_mode invalido (use entrance ou hero_spawns)."

    ent = defn.get("entrance")
    if start_mode == "entrance":
        if not (isinstance(ent, dict) and in_grid([ent.get("x"), ent.get("y")])):
            return False, "entrance ausente ou fora do grid."
        if tile_at([ent["x"], ent["y"]]) != FLOOR:
            return False, "entrance precisa estar em FLOOR (1)."
    else:
        spawns = defn.get("hero_spawns")
        if not isinstance(spawns, list) or not spawns:
            return False, "hero_spawns deve ter ao menos uma posicao."
        if len(spawns) > 6:
            return False, "hero_spawns pode ter no maximo 6 posicoes."
        usados = set()
        for spawn in spawns:
            if not isinstance(spawn, dict):
                return False, "cada hero_spawn deve ser um objeto JSON."
            cls_id = spawn.get("class_id")
            if cls_id not in set(CLASSES):
                return False, f"hero_spawn com class_id desconhecido: {cls_id!r}."
            if cls_id in usados:
                return False, f"ha mais de uma posicao inicial para {cls_id!r}."
            usados.add(cls_id)
            pos = spawn.get("pos")
            if not in_grid(pos):
                return False, f"hero_spawn de {cls_id!r} fora do grid: {pos!r}."
            if tile_at(pos) != FLOOR:
                return False, f"hero_spawn de {cls_id!r} precisa estar em FLOOR (1)."

    def _as_list(key):
        """defn[key] como lista (ausente/None → []); levanta sentinela se tipo errado."""
        v = defn.get(key)
        return [] if v is None else v

    rooms = _as_list("rooms")
    if not isinstance(rooms, list):
        return False, "rooms deve ser uma lista."
    for r in rooms:
        if not isinstance(r, dict):
            return False, "cada sala deve ser um objeto JSON."
    # Precisa de â‰¥1 sala e de uma sala de entrada â€” enter_dungeon usa a sala
    # role=="entrance" no modo tradicional; hero_spawns pode iniciar em salas comuns.
    if not rooms:
        return False, "a masmorra precisa de ao menos uma sala."
    if start_mode == "entrance" and not any(r.get("role") == "entrance" for r in rooms):
        return False, "nenhuma sala com role 'entrance'."
    room_ids = {r.get("id") for r in rooms}
    if start_mode == "hero_spawns":
        for spawn in defn.get("hero_spawns", []):
            room_id = spawn.get("room_id")
            if room_id is not None and room_id not in room_ids:
                return False, f"hero_spawn com room_id inexistente: {room_id!r}."
    for r in rooms:
        for d in (r.get("doors") or []):
            if not in_grid(d) or tile_at(d) != DOOR:
                return False, f"porta {d} da sala {r.get('id')} não é um tile DOOR (2)."
        orientations = r.get("door_orientations") or {}
        if not isinstance(orientations, dict):
            return False, f"door_orientations da sala {r.get('id')} deve ser um objeto."
        declared = {f"{d[0]},{d[1]}" for d in (r.get("doors") or []) if isinstance(d, (list, tuple)) and len(d) >= 2}
        for key, value in orientations.items():
            if key not in declared:
                return False, f"orientação de porta não declarada na sala {r.get('id')}: {key}."
            if not isinstance(value, int) or isinstance(value, bool) or value not in (0, 1, 2, 3):
                return False, f"orientação de porta inválida em {key}: {value!r}."

    monsters = _as_list("monsters")
    if not isinstance(monsters, list):
        return False, "monsters deve ser uma lista."
    tipos_monstro = {m["type"] for m in MONSTER_DEFS}
    for mo in monsters:
        if not isinstance(mo, dict):
            return False, "cada monstro deve ser um objeto JSON."
        if mo.get("type") not in tipos_monstro:
            return False, f"monstro tipo desconhecido: {mo.get('type')!r}."
        if not in_grid(mo.get("pos")) or tile_at(mo["pos"]) == WALL:
            return False, f"monstro em casa inválida: {mo.get('pos')}."
        # room_id vazio/None Ã© vÃ¡lido (monstro "sem sala") â€” espelha o editor.
        if mo.get("room_id") is not None and mo.get("room_id") not in room_ids:
            return False, f"monstro com room_id inexistente: {mo.get('room_id')!r}."
        vs = mo.get("vscale")
        if vs is not None and (not isinstance(vs, list) or len(vs) != 2
                               or any(isinstance(v, bool) or not isinstance(v, (int, float))
                                      or not math.isfinite(v) for v in vs)):
            return False, "vscale do monstro deve ter duas escalas numéricas."

    chests = _as_list("chests")
    if not isinstance(chests, list):
        return False, "chests deve ser uma lista."
    for ch in chests:
        if not isinstance(ch, dict):
            return False, "cada baú deve ser um objeto JSON."
        if not in_grid(ch.get("pos")) or tile_at(ch["pos"]) == WALL:
            return False, f"baú em casa inválida: {ch.get('pos')}."
        gold = ch.get("gold", 0)
        if isinstance(gold, bool) or not isinstance(gold, (int, float)) or gold < 0:
            return False, "baú com gold inválido ou negativo."
        for it in (ch.get("items") or []):
            if not isinstance(it, dict):
                return False, f"item de baú inválido: {it!r}."
            if it.get("id") not in _DUNGEON_ITEM_CATALOG:
                return False, f"item de baú desconhecido: {it.get('id')!r}."

    traps = _as_list("traps")
    if not isinstance(traps, list):
        return False, "traps deve ser uma lista."
    for tr in traps:
        if not isinstance(tr, dict):
            return False, "cada armadilha deve ser um objeto JSON."
        if tr.get("tipo") not in ARMADILHAS:
            return False, f"armadilha tipo desconhecido: {tr.get('tipo')!r}."
        if ARMADILHAS[tr["tipo"]].get("apenas_objeto"):
            return False, f"{tr['tipo']} só pode ser configurada em uma decoração/objeto."
        if not in_grid(tr.get("pos")) or tile_at(tr["pos"]) == WALL:
            return False, f"armadilha em casa inválida: {tr.get('pos')}."
        if ARMADILHAS[tr["tipo"]].get("custo_veneno") and tr.get("veneno_id") not in VENENOS:
            return False, f"{tr['tipo']} exige veneno_id válido: {tr.get('veneno_id')!r}."
        if tr.get("veneno_id") is not None and tr.get("veneno_id") not in VENENOS:
            return False, f"{tr['tipo']} recebeu veneno_id inválido: {tr.get('veneno_id')!r}."
        if tr["tipo"] == "armadilha_teletransporte":
            destino = tr.get("saida")
            if not in_grid(destino) or tile_at(destino) != FLOOR:
                return False, "armadilha_teletransporte exige uma saída em quadrado de chão."
        if tr["tipo"] == "armadilha_maldicao":
            mode = tr.get("curse_mode", "aleatoria")
            if mode not in {"especifica", "aleatoria"}:
                return False, "armadilha_maldicao: curse_mode inválido."
            if mode == "especifica" and tr.get("curse_id") not in MALDICOES:
                return False, "armadilha_maldicao específica exige curse_id válido."
            if mode == "aleatoria" and _maldicao_categoria(tr.get("curse_category", "leve")) not in {"leve", "media", "grave"}:
                return False, "armadilha_maldicao: curse_category inválida."
        if tr.get("image") is not None and not isinstance(tr.get("image"), str):
            return False, "trap.image deve ser uma string (nome do arquivo em assets/objetos)."

    pr = defn.get("prisoner")
    if pr is not None:
        if not isinstance(pr, dict):
            return False, "prisoner deve ser um objeto JSON."
        if not in_grid(pr.get("pos")) or tile_at(pr["pos"]) == WALL:
            return False, f"prisioneiro em casa inválida: {pr.get('pos')}."
        if pr.get("room_id") is not None and pr.get("room_id") not in room_ids:
            return False, f"prisioneiro com room_id inexistente: {pr.get('room_id')!r}."
        if pr.get("image") is not None and not isinstance(pr.get("image"), str):
            return False, "prisoner.image deve ser uma string (caminho do arquivo)."

    ex = defn.get("exit")
    if ex is not None and not in_grid([ex.get("x"), ex.get("y")]):
        return False, "exit fora do grid."

    if start_mode == "entrance":
        if _contar_chao_alcancavel(tiles, w, h, [ent["x"], ent["y"]], limite=6) < 6:
            return False, "menos de 6 casas de chão alcançáveis a partir da entrada."
    else:
        for spawn in defn.get("hero_spawns", []):
            if _contar_chao_alcancavel(tiles, w, h, spawn["pos"], limite=1) < 1:
                return False, f"hero_spawn de {spawn['class_id']!r} não está em uma casa caminhável."

    decors = defn.get("decorations", [])
    if not isinstance(decors, list):
        return False, "decorations deve ser uma lista."
    grid_w = defn["grid"]["w"]; grid_h = defn["grid"]["h"]
    ocupadas = set()
    for de in decors:
        if not isinstance(de, dict):
            return False, "cada decoração deve ser um objeto JSON."
        dtype = de.get("type")
        meta = DECOR_TYPES.get(dtype)
        if not meta:
            return False, f"decoração tipo desconhecido: {dtype!r}."
        pos = de.get("pos")
        if not (isinstance(pos, list) and len(pos) == 2 and in_grid(pos)):
            return False, f"decoração com pos inválida: {pos!r}."
        facing = de.get("facing")
        if facing is None:
            facing = [0, 1]
        elif not (isinstance(facing, list) and len(facing) == 2
                  and all(isinstance(c, int) and not isinstance(c, bool) for c in facing)):
            return False, f"decoração com facing inválido: {facing!r}."
        if meta["special"] == "wall":
            # A face aponta para a casa jogÃ¡vel diante da parede. Assim a arte
            # nunca aparece do lado externo/fechado da masmorra.
            if facing not in ([1, 0], [-1, 0], [0, 1], [0, -1]):
                return False, f"decoração de parede {dtype} exige uma face cardinal."
            fx, fy = pos[0] + facing[0], pos[1] + facing[1]
            if tile_at(pos) != WALL:
                return False, f"decoração de parede {dtype} precisa estar em uma parede."
            if not (0 <= fx < grid_w and 0 <= fy < grid_h) or tile_at([fx, fy]) != FLOOR:
                return False, f"face da decoração de parede {dtype} não aponta para um chão adjacente."
            key = (pos[0], pos[1], facing[0], facing[1])
            if key in ocupadas:
                return False, f"duas decorações na mesma face de parede em {pos}."
            ocupadas.add(key)
            continue
        # Footprint efetivo: usa o override por-objeto `size` quando presente
        # (espelha _decor_base_size / o editor), senÃ£o o tamanho do catÃ¡logo.
        ov = de.get("size")
        if isinstance(ov, list) and len(ov) == 2 \
           and all(isinstance(c, int) and not isinstance(c, bool) and c >= 1 for c in ov):
            w_d, h_d = ov
        else:
            w_d, h_d = meta["size"]
        ew, eh = (h_d, w_d) if (facing and facing[0] != 0) else (w_d, h_d)
        # ChÃ£o (special:floor) Ã© camada de PISO: pode coexistir com qualquer objeto
        # na mesma casa (nÃ£o conta como ocupaÃ§Ã£o). Dois objetos nÃ£o-piso ainda nÃ£o
        # podem se sobrepor.
        is_floor = (meta["special"] == "floor")
        for i in range(ew):
            for j in range(eh):
                tx, ty = pos[0] + i, pos[1] + j
                if not (0 <= tx < grid_w and 0 <= ty < grid_h):
                    return False, f"decoração {dtype} fora do grid em ({tx},{ty})."
                if tile_at([tx, ty]) != FLOOR:
                    return False, f"decoração {dtype} precisa estar sobre chão em ({tx},{ty})."
                if not is_floor:
                    if (tx, ty) in ocupadas:
                        return False, f"decorações sobrepostas em ({tx},{ty})."
                    ocupadas.add((tx, ty))
        loot = de.get("loot")
        if loot is not None:
            if not meta["loot_capaz"]:
                return False, f"decoração {dtype} não pode conter loot."
            gold = loot.get("gold", 0)
            if isinstance(gold, bool) or not isinstance(gold, (int, float)) or gold < 0:
                return False, "decoração com gold inválido."
            for it in (loot.get("items") or []):
                if not isinstance(it, dict) or it.get("id") not in _DUNGEON_ITEM_CATALOG:
                    return False, f"item de loot inválido: {it!r}."
        if meta["special"] == "fountain":
            ch = de.get("charges", 0)
            if isinstance(ch, bool) or not isinstance(ch, int) or ch < 0:
                return False, "fonte com charges inválido."
        if de.get("key_objective") is not None and not isinstance(de.get("key_objective"), bool):
            return False, "key_objective da decoração deve ser booleano."
        arm_monstro = de.get("chest_trap_monster_type")
        if arm_monstro is not None and arm_monstro not in {m["type"] for m in MONSTER_DEFS}:
            return False, f"baú-armadilha com monstro desconhecido: {arm_monstro!r}."
        decor_trap = de.get("trap")
        if decor_trap is not None:
            if not isinstance(decor_trap, dict) or decor_trap.get("tipo") not in ARMADILHAS:
                return False, f"armadilha de decoração inválida: {decor_trap!r}."
            trap_tipo = decor_trap["tipo"]
            if ARMADILHAS[trap_tipo].get("custo_veneno") \
                    and decor_trap.get("veneno_id") not in VENENOS:
                return False, f"{trap_tipo} na decoração exige veneno_id válido."
            if decor_trap.get("veneno_id") is not None and decor_trap.get("veneno_id") not in VENENOS:
                return False, f"{trap_tipo} na decoração recebeu veneno_id inválido."
            if trap_tipo == "armadilha_teletransporte":
                destino = decor_trap.get("saida")
                if not in_grid(destino) or tile_at(destino) != FLOOR:
                    return False, "armadilha de teletransporte na decoração exige saída em chão."
            if trap_tipo == "armadilha_maldicao":
                mode = decor_trap.get("curse_mode", "aleatoria")
                if mode not in {"especifica", "aleatoria"}:
                    return False, "armadilha_maldicao na decoracao: curse_mode invalido."
                if mode == "especifica" and decor_trap.get("curse_id") not in MALDICOES:
                    return False, "armadilha_maldicao na decoracao exige curse_id valido."
                if mode == "aleatoria" and _maldicao_categoria(decor_trap.get("curse_category", "leve")) not in {"leve", "media", "grave"}:
                    return False, "armadilha_maldicao na decoracao: curse_category invalida."
        img = de.get("image")
        if img is not None:
            if not isinstance(img, str) or os.path.basename(img) != img \
               or not img.lower().endswith(".png") or "\x00" in img:
                return False, f"decoração com image inválida: {img!r}."
            if not os.path.isfile(os.path.join(OBJETOS_DIR, img)):
                return False, f"image inexistente em assets/objetos: {img!r}."

    reinf = defn.get("master_reinforcements", [])
    if not isinstance(reinf, list):
        return False, "master_reinforcements deve ser uma lista."
    _valid_monster_types = {d["type"] for d in MONSTER_DEFS}
    for entry in reinf:
        if not isinstance(entry, dict):
            return False, "cada reforço deve ser um objeto JSON."
        if entry.get("type") not in _valid_monster_types:
            return False, f"reforço com tipo de monstro desconhecido: {entry.get('type')!r}."
        c = entry.get("count")
        if not isinstance(c, int) or isinstance(c, bool) or c < 1:
            return False, f"reforço com count inválido: {c!r} (inteiro ≥ 1)."

    ep = defn.get("expected_party")
    if ep is not None:
        if not isinstance(ep, dict):
            return False, "expected_party deve ser um objeto JSON."
        heroes = ep.get("heroes"); lv = ep.get("level")
        if not isinstance(heroes, int) or isinstance(heroes, bool) or not (1 <= heroes <= 6):
            return False, f"expected_party.heroes inválido: {heroes!r} (inteiro 1–6)."
        if not isinstance(lv, int) or isinstance(lv, bool) or lv < 1:
            return False, f"expected_party.level inválido: {lv!r} (inteiro ≥ 1)."

    sp = defn.get("saida_permitida")
    if sp is not None and not isinstance(sp, bool):
        return False, f"saida_permitida inválido: {sp!r} (booleano)."

    _rooms_req = [r for r in (defn.get("rooms") or []) if isinstance(r, dict) and r.get("required")]
    for _r in (defn.get("rooms") or []):
        if isinstance(_r, dict) and _r.get("required_mode") not in (None, "visit", "clear"):
            return False, f"required_mode inválido: {_r.get('required_mode')!r} (visit|clear)."
    _objs = []
    _o = defn.get("objectives") or {}
    if _o.get("primary"): _objs.append(_o["primary"])
    _objs.extend(_o.get("secondary") or [])
    ex = defn.get("exit")
    if ex is not None:
        if not (isinstance(ex, dict) and in_grid([ex.get("x"), ex.get("y")])):
            return False, "exit ausente ou fora do grid."
        if tile_at([ex["x"], ex["y"]]) != FLOOR:
            return False, "exit precisa estar em FLOOR (1)."
    for _ob in _objs:
        if isinstance(_ob, dict) and _ob.get("type") == "salas_obrigatorias" and not _rooms_req:
            return False, "objetivo salas_obrigatorias sem salas marcadas como obrigatórias."
        if isinstance(_ob, dict) and _ob.get("type") == "all_heroes_at_exit" and ex is None:
            return False, "objetivo all_heroes_at_exit exige uma saída (exit)."

    for _f in (defn.get("falas") or []):
        if not isinstance(_f, dict):
            return False, "cada fala deve ser um objeto JSON."
        if not (_f.get("texto") or "").strip():
            return False, "fala com texto vazio."
        _tg = (_f.get("trigger") or {}).get("tipo")
        if _tg not in ("proximidade", "sala", "manual"):
            return False, f"fala com gatilho inválido: {_tg!r} (proximidade|sala|manual)."
        if not in_grid(_f.get("pos")):
            return False, f"fala em casa inválida: {_f.get('pos')}."
        if not _e_licao(_f):
            continue
        # ── Lição de tutorial ──
        if _tg == "manual":
            return False, "lição de tutorial não aceita gatilho manual."
        _cls = _f.get("classe")
        if _cls is not None and _cls not in LICAO_CLASSES:
            return False, f"lição com classe inválida: {_cls!r}."
        _ord = _f.get("ordem")
        if _ord is not None and (not isinstance(_ord, int) or isinstance(_ord, bool)):
            return False, "ordem de lição deve ser um inteiro."
        _tar = _f.get("tarefa")
        if _tar is None:
            continue
        if not isinstance(_tar, dict):
            return False, "tarefa de lição deve ser um objeto JSON."
        if _tar.get("tipo") not in LICAO_VERBOS:
            return False, f"lição com tipo de tarefa inválido: {_tar.get('tipo')!r}."
        _vezes = _tar.get("vezes", 1)
        if not isinstance(_vezes, int) or isinstance(_vezes, bool) or _vezes < 1:
            return False, "tarefa de lição precisa de vezes maior ou igual a 1."
        if not (_tar.get("texto_curto") or "").strip():
            return False, "tarefa de lição sem texto_curto."
        _alvo = _tar.get("alvo")
        if _alvo not in (None, "", []):
            if _tar["tipo"] in LICAO_VERBOS_CASA:
                if not in_grid(_alvo):
                    return False, f"alvo de {_tar['tipo']} fora do mapa: {_alvo}."
            elif not isinstance(_alvo, str):
                return False, f"alvo de {_tar['tipo']} deve ser um texto."

    _ordens_vistas = set()
    for _f in (defn.get("falas") or []):
        if not _e_licao(_f) or _f.get("ordem") is None:
            continue
        _chave = (_f.get("classe"), _f["ordem"])
        if _chave in _ordens_vistas:
            return False, (f"duas lições com a mesma ordem {_chave[1]} para "
                           f"{_chave[0] or 'todas as classes'}.")
        _ordens_vistas.add(_chave)

    # Passagens autoradas: a mecÃ¢nica permanece uma parede atÃ© ser ativada;
    # a ilusÃ³ria continua WALL no mapa, mas o movimento de herÃ³is a atravessa.
    passages = defn.get("secret_passages", [])
    if not isinstance(passages, list):
        return False, "secret_passages deve ser uma lista."
    decor_ids = set()
    for i, de in enumerate(decors):
        did = de.get("id", f"dec_{i}")
        if not isinstance(did, str) or not did or did in decor_ids:
            return False, "ids de decorações devem ser strings únicas."
        decor_ids.add(did)
    seen_passages = set()
    for sp in passages:
        if not isinstance(sp, dict):
            return False, "cada passagem secreta deve ser um objeto JSON."
        sid = sp.get("id")
        if not isinstance(sid, str) or not sid or sid in seen_passages:
            return False, "ids de passagens secretas devem ser strings únicas."
        seen_passages.add(sid)
        if sp.get("type") not in ("mechanism", "illusion"):
            return False, "passagem secreta deve ter type mechanism ou illusion."
        pos = sp.get("pos")
        if not in_grid(pos) or tile_at(pos) != WALL:
            return False, "passagem secreta precisa ser colocada em uma parede."
        keys = sp.get("key_decor_ids", [])
        if not isinstance(keys, list) or any(not isinstance(k, str) or k not in decor_ids for k in keys):
            return False, "passagem secreta referencia uma decoração-chave inválida."
        if len(set(keys)) != len(keys):
            return False, "uma decoração-chave foi repetida na passagem secreta."
        if sp.get("type") == "mechanism" and not keys:
            return False, "passagem mecânica exige ao menos uma decoração-chave."
        if sp.get("keys_mode", "any") not in ("any", "all"):
            return False, "keys_mode deve ser any ou all."

    # Condicoes opcionais de portas: ausencia preserva o comportamento legado.
    door_conditions = defn.get("door_conditions") or {}
    if not isinstance(door_conditions, dict):
        return False, "door_conditions deve ser um objeto."
    decor_by_id = {de.get("id"): de for de in decors if isinstance(de, dict)}
    _licao_ids = {f.get("id") for f in (defn.get("falas") or [])
                  if _e_licao(f) and (f.get("tarefa"))}
    for key, cond in door_conditions.items():
        if not isinstance(key, str) or not re.fullmatch(r"\d+,\d+", key):
            return False, f"chave de condicao de porta invalida: {key!r}."
        dx, dy = (int(v) for v in key.split(","))
        if not in_grid([dx, dy]) or tile_at([dx, dy]) != DOOR:
            return False, f"condicao de abertura referencia uma casa que nao e porta: {key}."
        if not isinstance(cond, dict) or cond.get("type") not in ("item", "decor", "licao"):
            return False, f"condicao de porta invalida em {key}: use item, decor ou licao."
        if cond["type"] == "licao":
            if cond.get("licao_id") not in _licao_ids:
                return False, (f"porta {key} aponta para uma licao que nao existe ou "
                               f"nao tem tarefa: {cond.get('licao_id')!r}.")
        elif cond["type"] == "item":
            if cond.get("item_id") not in _DUNGEON_ITEM_CATALOG:
                return False, f"item-chave invalido na porta {key}: {cond.get('item_id')!r}."
        else:
            keys = cond.get("key_decor_ids", [])
            if (not isinstance(keys, list) or not keys
                    or any(not isinstance(k, str) or k not in decor_by_id for k in keys)):
                return False, f"porta {key} precisa de objetos-chave validos."
            if len(set(keys)) != len(keys):
                return False, f"porta {key} repete um objeto-chave."
            if cond.get("keys_mode", "any") not in ("any", "all"):
                return False, f"keys_mode invalido na porta {key}."
            if any(not decor_by_id[k].get("key_objective") for k in keys):
                return False, f"porta {key} referencia decoracao que nao esta marcada como objeto-chave."

    mats = defn.get("materiais")
    if mats is not None:
        if not isinstance(mats, dict):
            return False, "materiais deve ser um objeto (mapa 'x,y' -> id)."
        for key, mid in mats.items():
            meta = MATERIAIS.get(mid)
            if meta is None:
                return False, f"material desconhecido: {mid!r}."
            if not isinstance(key, str):
                return False, f"chave de material inválida: {key!r}."
            partes = key.split(",")
            if len(partes) != 2:
                return False, f"chave de material inválida: {key!r} (esperado 'x,y')."
            try:
                mx, my = int(partes[0]), int(partes[1])
            except ValueError:
                return False, f"chave de material inválida: {key!r} (esperado 'x,y')."
            if not (0 <= mx < w and 0 <= my < h):
                return False, f"material fora do grid em {key!r}."
            t = tiles[my][mx]
            if meta["categoria"] == "piso" and t not in (FLOOR, DOOR):
                return False, f"material de piso {mid!r} em casa não-chão ({mx},{my})."
            if meta["categoria"] == "parede" and t != WALL:
                return False, f"material de parede {mid!r} em casa não-parede ({mx},{my})."

    return True, "ok"

def hidratar_itens_bau(items):
    """Resolve [{'id': ...}] nos dicts completos de CHEST_ITEMS. Ignora ids
    desconhecidos (a validação já recusa antes de chegar aqui)."""
    out = []
    for it in items or []:
        if not isinstance(it, dict):
            continue
        inst = _resolver_loot_instrumento(it)   # token de instrumento procedural (Fase 4a)
        if inst:
            out.append(inst); continue
        base = _DUNGEON_ITEM_CATALOG.get(it.get("id"))
        if base:
            out.append(deepcopy(base))
    return out

def make_authored_trap(tdef):
    """Cria o dict de uma armadilha de masmorra autorada (hostil, oculta),
    no formato de self.armadilhas. Espelha _gerar_armadilhas_kobold.
    Pressupõe `tdef` já validado por validar_dungeon (tipo/pos presentes)."""
    tipo = tdef["tipo"]
    meta = ARMADILHAS[tipo]
    arm = {
        "id":            new_id(),
        "tipo":          tipo,
        "pos":           [tdef["pos"][0], tdef["pos"][1]],
        "icone":         meta["icone"],
        "nome":          meta["nome"],
        "visivel":       False,
        "ativada":       False,
        "aliada":        False,
        "so_luccas":     False,
        "efeitos_ativos": [],
    }
    if meta.get("custo_veneno") or meta.get("permite_veneno"):
        arm["veneno_id"] = tdef.get("veneno_id")
    if tipo == "armadilha_teletransporte":
        arm["saida"] = list(tdef.get("saida") or [])
    if tipo == "armadilha_maldicao":
        arm["curse_mode"] = tdef.get("curse_mode", "aleatoria")
        arm["curse_id"] = tdef.get("curse_id", "maos_tremulas")
        arm["curse_category"] = _maldicao_categoria(tdef.get("curse_category", "leve"))
        arm["save"] = tdef.get("save", meta["save"])
        arm["dificuldade"] = _monster_int(tdef.get("dificuldade", meta["dificuldade"]), meta["dificuldade"], 1, 40)
    if tdef.get("image"):
        arm["image"] = tdef["image"]   # PNG opcional (assets/objetos) â€” sÃ³ some quando revelada
    return arm

def carregar_dungeon(file):
    """Lê e parseia um arquivo de DUNGEONS_DIR. Retorna dict ou None."""
    if not isinstance(file, str) or not file or file != os.path.basename(file):
        return None  # proteÃ§Ã£o contra path traversal (sem componente de diretÃ³rio)
    caminho = os.path.join(DUNGEONS_DIR, file)
    try:
        with open(caminho, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def listar_dungeons():
    """Varre DUNGEONS_DIR e devolve [{id, name, file}] das masmorras válidas."""
    out = []
    try:
        arquivos = sorted(f for f in os.listdir(DUNGEONS_DIR) if f.endswith(".json"))
    except Exception:
        return out
    for file in arquivos:
        defn = carregar_dungeon(file)
        if not defn:
            continue
        ok, _ = validar_dungeon(defn)
        if ok:
            out.append({"id": defn.get("id", file), "name": defn.get("name", file), "file": file})
    return out

CAMPAIGNS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "campaigns")
SCENES_FILE = os.path.join(CAMPAIGNS_DIR, "cenas.json")

def _cenas_vazias():
    return {"schema_version": 1, "scenes": {}}

def carregar_cenas():
    """Biblioteca global de cinematics. Falhas de arquivo nunca impedem o jogo."""
    try:
        with open(SCENES_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if not isinstance(raw, dict) or not isinstance(raw.get("scenes"), dict):
            return _cenas_vazias()
        return {"schema_version": 1, "scenes": raw["scenes"]}
    except Exception:
        return _cenas_vazias()

def validar_cenas(raw):
    if not isinstance(raw, dict) or not isinstance(raw.get("scenes"), dict):
        return False, "biblioteca de cenas inválida"
    for sid, scene in raw["scenes"].items():
        if not isinstance(sid, str) or not re.fullmatch(r"[a-z0-9_]{1,80}", sid):
            return False, "id de cena inválido"
        if not isinstance(scene, dict) or not isinstance(scene.get("events", []), list):
            return False, f"cena inválida: {sid}"
        ids = set()
        for ev in scene["events"]:
            eid = ev.get("id") if isinstance(ev, dict) else None
            if not isinstance(eid, str) or not eid or eid in ids:
                return False, f"evento sem id único em {sid}"
            ids.add(eid)
        if scene.get("start") and scene["events"] and scene["start"] not in ids:
            return False, f"evento inicial inexistente em {sid}"
    return True, "ok"

SCENE_LIBRARY = carregar_cenas()

def carregar_campanha(file):
    """Lê e parseia um arquivo de CAMPAIGNS_DIR. Retorna dict ou None."""
    if not isinstance(file, str) or not file or file != os.path.basename(file):
        return None  # proteÃ§Ã£o contra path traversal
    caminho = os.path.join(CAMPAIGNS_DIR, file)
    try:
        with open(caminho, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def _fase_file(item):
    """O nome do arquivo de uma fase de campanha (string ou objeto {file,...})."""
    if isinstance(item, str):
        return item
    if isinstance(item, dict):
        return item.get("file")
    return None

def _fase_obj(item):
    """Normaliza uma fase para {file, intro, outro}."""
    if isinstance(item, str):
        return {"file": item, "intro": "", "outro": ""}
    if isinstance(item, dict):
        return {"file": item.get("file"), "intro": item.get("intro", ""), "outro": item.get("outro", "")}
    return {"file": None, "intro": "", "outro": ""}

def _etapa_file(item):
    """O arquivo de uma etapa de aventura (string legada ou objeto {file,...})."""
    if isinstance(item, str):
        return item
    if isinstance(item, dict):
        return item.get("file")
    return None

def _etapa_obj(item):
    """Normaliza uma etapa de aventura para {file, encadear, intro, outro}.
    `encadear` faz a próxima etapa começar imediatamente, sem passar pela cidade."""
    if isinstance(item, str):
        return {"file": item, "encadear": False, "intro": "", "outro": ""}
    if isinstance(item, dict):
        return {"file": item.get("file"), "encadear": bool(item.get("encadear")),
                "intro": item.get("intro", ""), "outro": item.get("outro", ""),
                "scene_trigger": item.get("scene_trigger")}
    return {"file": None, "encadear": False, "intro": "", "outro": "", "scene_trigger": None}

def _clean_espera(raw):
    """Normaliza a espera de retorno de uma aventura para
    {'modo': 'fixa'|'dados', 'rodadas': int, 'dados': str}. Fórmula inválida
    rebaixa o modo para 'fixa' — o autor nunca fica com uma espera quebrada."""
    raw = raw if isinstance(raw, dict) else {}
    modo = "dados" if raw.get("modo") == "dados" else "fixa"
    try:
        rodadas = max(0, min(99, int(raw.get("rodadas", 0))))
    except (TypeError, ValueError):
        rodadas = 0
    dados = str(raw.get("dados") or "").strip()[:16]
    if not re.fullmatch(r"\d{0,2}d\d{1,3}([+-]\d{1,3})?", dados):
        dados = ""
    if modo == "dados" and not dados:
        modo = "fixa"
    return {"modo": modo, "rodadas": rodadas, "dados": dados}

def _rolar_espera(espera):
    """Quantas rodadas o herói fica fora da masmorra nesta saída."""
    e = _clean_espera(espera)
    if e["modo"] == "dados":
        return max(0, roll_dice(e["dados"]))
    return e["rodadas"]

def _story_norm(val):
    """Normaliza um campo de história para {'slides': [...], 'audio': str|None}.
    Aceita string (legado = 1 slide de texto), objeto {'slides','audio'} ou vazio.
    Slides sem text nem image são descartados; fit default 'cover'."""
    if not val:
        return {"slides": [], "audio": None}
    if isinstance(val, str):
        return {"slides": [{"text": val}], "audio": None}
    if isinstance(val, dict):
        out = []
        for s in (val.get("slides") or []):
            if not isinstance(s, dict):
                continue
            slide = {}
            if isinstance(s.get("text"), str) and s["text"]:
                slide["text"] = s["text"]
            if isinstance(s.get("image"), str) and s["image"]:
                slide["image"] = s["image"]
            if not slide:
                continue
            slide["fit"] = "contain" if s.get("fit") == "contain" else "cover"
            out.append(slide)
        audio = val.get("audio")
        audio = audio if (isinstance(audio, str) and audio) else None
        return {"slides": out, "audio": audio}
    return {"slides": [], "audio": None}


_STORY_MEDIA_PREFIX = "assets/story/"

def _story_media_ok(caminho):
    """Mídia de história vem do cliente e é servida como arquivo estático:
    só vale caminho dentro de assets/story/, sem subir de diretório."""
    return (isinstance(caminho, str) and caminho.startswith(_STORY_MEDIA_PREFIX)
            and ".." not in caminho)

def _clean_story_field(raw):
    """Normaliza um campo de história do editor para persistência.
    Aceita string (legado/1 slide de texto) ou {'slides':[...], 'audio':...};
    devolve string, {'slides':[...], 'audio'?} ou "" quando não sobra nada."""
    if isinstance(raw, str):
        return raw.strip()[:2000]
    norm = _story_norm(raw)
    slides = []
    for s in norm["slides"][:20]:
        slide = {}
        if s.get("text"):
            slide["text"] = s["text"][:2000]
        if _story_media_ok(s.get("image")):
            slide["image"] = s["image"]
        if not slide:
            continue
        if s.get("fit") == "contain":
            slide["fit"] = "contain"
        slides.append(slide)
    if not slides:
        return ""
    out = {"slides": slides}
    if _story_media_ok(norm.get("audio")):
        out["audio"] = norm["audio"]
    return out

def _clean_location_scene_trigger(raw):
    """Normaliza a cena associada à entrada de uma etapa/local."""
    if not isinstance(raw, dict):
        return None
    sid = str(raw.get("scene_id") or "").strip()
    if not sid or sid not in (SCENE_LIBRARY.get("scenes") or {}):
        return None
    req = raw.get("requires") if isinstance(raw.get("requires"), dict) else {}
    def values(key):
        return [str(x).strip()[:100] for x in (req.get(key) or []) if str(x).strip()][:20]
    return {"scene_id": sid, "once": raw.get("once") is not False,
            "requires": {"keywords_all": values("keywords_all"),
                         "key_items_all": values("key_items_all")}}


def _story_beat(key, parts):
    """parts: lista de campos de história (string|objeto) na ORDEM de exibição.
    Retorna {'key','slides','audio'} ou None se não houver slides. O áudio é o
    primeiro não-nulo encontrado na ordem das partes."""
    slides, audio = [], None
    for p in parts:
        n = _story_norm(p)
        slides.extend(n["slides"])
        if audio is None and n["audio"]:
            audio = n["audio"]
    if not slides:
        return None
    return {"key": key, "slides": slides, "audio": audio}


def _validar_story(val, rotulo):
    """(ok, msg) — aceita string (legado) ou objeto {'slides':[...], 'audio'?}."""
    if isinstance(val, str):
        return True, "ok"
    if not isinstance(val, dict):
        return False, f"{rotulo}: deve ser texto ou objeto de história."
    slides = val.get("slides")
    if not isinstance(slides, list):
        return False, f"{rotulo}: 'slides' deve ser uma lista."
    for j, s in enumerate(slides):
        if not isinstance(s, dict):
            return False, f"{rotulo}: slide {j+1} deve ser um objeto."
        if "text" in s and not isinstance(s["text"], str):
            return False, f"{rotulo}: slide {j+1} 'text' deve ser texto."
        if "image" in s and not isinstance(s["image"], str):
            return False, f"{rotulo}: slide {j+1} 'image' deve ser texto."
        if "fit" in s and s["fit"] not in ("cover", "contain"):
            return False, f"{rotulo}: slide {j+1} 'fit' deve ser 'cover' ou 'contain'."
        if not (s.get("text") or s.get("image")):
            return False, f"{rotulo}: slide {j+1} precisa de texto ou imagem."
    if "audio" in val and not isinstance(val["audio"], str):
        return False, f"{rotulo}: 'audio' deve ser texto."
    return True, "ok"


def validar_campanha(defn):
    """Valida um dict de campanha. Retorna (ok: bool, msg: str). Cada fase deve
    existir em dungeons/ e passar em validar_dungeon."""
    if not isinstance(defn, dict):
        return False, "Campanha não é um objeto JSON."
    if defn.get("schema_version") != 1:
        return False, f"schema_version não suportado: {defn.get('schema_version')!r} (esperado 1)."
    # Campanhas novas são narrativas: entradas de masmorra vivem nos destinos do
    # mapa. Ainda aceitamos a lista antiga para campanhas já publicadas.
    dungeons = defn.get("dungeons", [])
    if not isinstance(dungeons, list):
        return False, "'dungeons' precisa ser uma lista quando informado."
    for k in ("intro", "outro"):
        if k in defn:
            ok, msg = _validar_story(defn[k], f"campanha '{k}'")
            if not ok:
                return False, msg
    allowed_scene_triggers = {"campaign_start", "city_enter", "dungeon_enter", "dungeon_complete", "keyword_obtained", "key_item_obtained"}
    for i, trigger in enumerate(defn.get("scene_triggers") or []):
        if not isinstance(trigger, dict): return False, f"gatilho de cena {i+1}: formato inválido."
        if not isinstance(trigger.get("scene_id"), str) or not trigger.get("scene_id").strip():
            return False, f"gatilho de cena {i+1}: escolha uma cena."
        if trigger.get("scene_id").strip() not in (SCENE_LIBRARY.get("scenes") or {}):
            return False, f"gatilho de cena {i+1}: cena inexistente."
        if trigger.get("when") not in allowed_scene_triggers:
            return False, f"gatilho de cena {i+1}: evento inválido."
        if trigger.get("when") in {"keyword_obtained", "key_item_obtained"} and not str(trigger.get("trigger_value") or "").strip():
            return False, f"gatilho de cena {i+1}: informe o valor que aciona a cena."
        if "requires" in trigger and not isinstance(trigger["requires"], dict):
            return False, f"gatilho de cena {i+1}: requisitos inválidos."
    for i, item in enumerate(dungeons):
        file = _fase_file(item)
        if not isinstance(file, str) or not file:
            return False, f"fase {i+1}: precisa de um 'file' (string)."
        if isinstance(item, dict):
            for k in ("intro", "outro"):
                if k in item:
                    ok, msg = _validar_story(item[k], f"fase {i+1} '{k}'")
                    if not ok:
                        return False, msg
        d = carregar_dungeon(file)
        if d is None:
            return False, f"fase {i+1}: masmorra '{file}' não encontrada."
        ok, msg = validar_dungeon(d)
        if not ok:
            return False, f"fase {i+1} ('{file}'): {msg}"
    return True, "ok"

def listar_campanhas():
    """Varre CAMPAIGNS_DIR e devolve [{id, name, file}] das campanhas válidas."""
    out = []
    try:
        arquivos = sorted(f for f in os.listdir(CAMPAIGNS_DIR) if f.endswith(".json"))
    except Exception:
        return out
    for file in arquivos:
        defn = carregar_campanha(file)
        if not defn:
            continue
        ok, _ = validar_campanha(defn)
        if ok:
            out.append({"id": defn.get("id", file), "name": defn.get("name", file), "file": file})
    return out

