def _default_city_shops():
    return {city_id: ({shop_id: [item["id"] for item in source]
                       for shop_id, source in CITY_SHOP_SOURCES.items()}
                      if city_id == "alva_e_luz" else {})
            for city_id in WORLD_LOCATIONS}

CITY_SHOPS = _default_city_shops()

def _load_city_shops():
    try:
        with open(CITY_SHOPS_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if not isinstance(raw, dict): return
        for city_id, shops in raw.items():
            if city_id not in CITY_SHOPS or not isinstance(shops, dict): continue
            for shop_id, item_ids in shops.items():
                if shop_id in CITY_SHOP_SOURCES and isinstance(item_ids, list):
                    allowed = {item["id"] for item in CITY_SHOP_SOURCES[shop_id]}
                    CITY_SHOPS[city_id][shop_id] = [str(i) for i in item_ids if str(i) in allowed]
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        pass

def _save_city_shops():
    temp = CITY_SHOPS_FILE + ".tmp"
    with open(temp, "w", encoding="utf-8") as f: json.dump(CITY_SHOPS, f, ensure_ascii=False, indent=2)
    os.replace(temp, CITY_SHOPS_FILE)

def _city_shop_items(city_id, shop_id):
    ids = set(CITY_SHOPS.get(city_id, {}).get(shop_id, []))
    return [item for item in CITY_SHOP_SOURCES.get(shop_id, []) if item["id"] in ids]

_load_city_shops()

def _sincronizar_cidades_derivadas():
    """Garante uma entrada vazia de lojas/pontos/taverna para cada cidade e
    remove as sobras de cidades excluídas. Usado após salvar pelo editor (no
    boot cada subsistema já se semeia na sua própria declaração)."""
    for cid in [c for c in CITY_SHOPS if c not in WORLD_LOCATIONS]:
        del CITY_SHOPS[cid]
    for cid in [c for c in CITY_MAP_POINTS if c not in WORLD_LOCATIONS]:
        del CITY_MAP_POINTS[cid]
    for cid in [c for c in CITY_SCENES if c not in WORLD_LOCATIONS]:
        del CITY_SCENES[cid]
    for cid in WORLD_LOCATIONS:
        CITY_SHOPS.setdefault(cid, {})
        CITY_MAP_POINTS.setdefault(cid, {})
        CITY_SCENES.setdefault(cid, {})
    _garantir_pontos_implicitos()

# Posição inicial de cada ponto que a cidade ganha sozinha (Caravana + o prédio
# de cada loja que a cidade tem). O cliente NÃO desenha mais nenhum marcador
# fixo: tudo que aparece na ilustração vem de CITY_MAP_POINTS, senão o jogador
# via um ponto que o editor não tinha como mostrar nem reposicionar.
_PONTO_PADRAO = {"taverna": (32.0, 46.0), "templo": (67.0, 35.0), "ferreiro": (83.0, 38.0),
                 "guilda": (52.0, 21.0), "mercador": (50.0, 40.0), "caravana": (42.0, 63.0)}
# Cada prédio nativo e as chaves de loja que o fazem existir na cidade.
_PONTO_LOJAS = {"ferreiro": ("ferreiro_weapon", "ferreiro_armor", "ferreiro_ammo"),
                "mercador": ("mercador",), "templo": ("templo",), "taverna": ("taverna",)}

def _garantir_pontos_implicitos():
    """Materializa como ponto editável tudo que a cidade mostraria sozinho: a
    Caravana de Viagem e o prédio de cada loja existente. Só cria o que falta —
    se já houver um ponto daquele tipo (mesmo com outro id), respeita o autor."""
    for cid, pontos in CITY_MAP_POINTS.items():
        lojas = CITY_SHOPS.get(cid, {})
        tipos = ["caravana"] + [b for b, chaves in _PONTO_LOJAS.items()
                                if any(isinstance(lojas.get(k), list) for k in chaves)]
        existentes = {str(p.get("type") or pid) for pid, p in pontos.items()}
        for tipo in tipos:
            if tipo in existentes or tipo in pontos:
                continue
            x, y = _PONTO_PADRAO[tipo]
            pontos[tipo] = {"x": x, "y": y, "type": tipo}
        # Vínculo implícito: um ponto cujo id casa com o id de uma cena da cidade
        # já nasce ligado a ela. É o que faz a taverna migrada abrir sozinha,
        # sem nenhum caso especial no runtime.
        cenas = CITY_SCENES.get(cid, {})
        for pid_ponto, ponto in pontos.items():
            if not ponto.get("scene") and pid_ponto in cenas:
                ponto["scene"] = pid_ponto

_sincronizar_cidades_derivadas()
