def gm(key):
    """Uma variante sorteada do pool de narração de ambiente, como texto TARDIO.

    O sorteio acontece UMA vez e o idioma é resolvido no envio — senão dois
    jogadores na mesma sala leriam variantes DIFERENTES do mesmo evento. O `GM`
    continua sendo a fonte do português; as chaves moram no narracao.js."""
    return T(f"narracao.gm.{key}.{random.randrange(len(GM[key]))}")

# â”€â”€â”€ MAP GENERATION â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

def generate_dungeon():
    """Generate a dungeon map with rooms connected by corridors."""
    tiles = [[WALL] * MAP_W for _ in range(MAP_H)]
    rooms = []

    # Try to place rooms
    for _ in range(60):
        w = random.randint(4, 8)
        h = random.randint(4, 8)
        x = random.randint(1, MAP_W - w - 1)
        y = random.randint(1, MAP_H - h - 1)
        # Check overlap with buffer
        overlap = any(
            rx - 1 <= x + w and rx + rw + 1 >= x and
            ry - 1 <= y + h and ry + rh + 1 >= y
            for rx, ry, rw, rh in rooms
        )
        if not overlap:
            rooms.append((x, y, w, h))
            if len(rooms) >= 10:
                break

    # Carve rooms
    for x, y, w, h in rooms:
        for ry in range(y, y + h):
            for rx in range(x, x + w):
                tiles[ry][rx] = FLOOR

    # Connect rooms with L-shaped corridors
    for i in range(1, len(rooms)):
        ax, ay = rooms[i-1][0] + rooms[i-1][2]//2, rooms[i-1][1] + rooms[i-1][3]//2
        bx, by = rooms[i][0] + rooms[i][2]//2,     rooms[i][1] + rooms[i][3]//2
        # Horizontal then vertical
        for rx in range(min(ax, bx), max(ax, bx) + 1):
            tiles[ay][rx] = FLOOR
        for ry in range(min(ay, by), max(ay, by) + 1):
            tiles[ry][bx] = FLOOR

    # Assign room roles
    random.shuffle(rooms)
    room_data = []
    roles = (
        ["entrance"] +
        ["monster"] * 3 +
        ["chest"] * 2 +
        ["trap"] * 1 +
        ["empty"] * max(0, len(rooms) - 8) +
        ["boss"]
    )
    for i, (x, y, w, h) in enumerate(rooms):
        role = roles[i] if i < len(roles) else "empty"
        cx, cy = x + w//2, y + h//2
        room_data.append({
            "id": i, "x": x, "y": y, "w": w, "h": h,
            "cx": cx, "cy": cy, "role": role,
            "cleared": role in ("entrance", "empty"),
            "looted": False,
            # Salas comeÃ§am trancadas (porta fechada), exceto a entrada. HerÃ³is
            # precisam abrir a porta para entrar; monstros lÃ¡ dentro ficam
            # dormentes atÃ© a porta ser aberta.
            "locked": role != "entrance",
            "doors": [],   # tiles DOOR no anel externo (entradas da sala)
        })

    # â”€â”€ Detect doorways: UMA porta por entrada/saÃ­da â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Uma "abertura" Ã© um grupo contÃ­guo de casas de corredor coladas Ã  borda
    # interna da sala. Cada abertura recebe UMA porta (no limiar, lado do
    # corredor); as demais casas da abertura sÃ£o fechadas SELANDO a parede do
    # lado da SALA (a borda interna vira WALL). Nunca fechamos o corredor â€” isso
    # poderia cortar passagens e desconectar o mapa. Resultado: cada sala fica
    # com paredes limpas e portas de 1 casa exatamente nas entradas/saÃ­das.
    for room in room_data:
        rx0, ry0, rw, rh = room["x"], room["y"], room["w"], room["h"]
        # casa de corredor (fora) -> casa de borda interna correspondente
        corr_to_edge = {}
        for iy in range(ry0, ry0 + rh):
            for ix in range(rx0, rx0 + rw):
                if not (ix == rx0 or ix == rx0 + rw - 1 or iy == ry0 or iy == ry0 + rh - 1):
                    continue
                for dx, dy in ((0, -1), (0, 1), (-1, 0), (1, 0)):
                    nx, ny = ix + dx, iy + dy
                    if not (0 <= nx < MAP_W and 0 <= ny < MAP_H):
                        continue
                    if room_contains(room, nx, ny):
                        continue  # ainda dentro da sala
                    if tiles[ny][nx] in (FLOOR, DOOR):
                        corr_to_edge.setdefault((nx, ny), (ix, iy))

        # agrupa casas de corredor contÃ­guas (4-dir) â†’ cada grupo Ã© uma abertura
        corr_tiles = set(corr_to_edge)
        nao_visto  = set(corr_tiles)
        aberturas  = []
        while nao_visto:
            ini = nao_visto.pop()
            pilha = [ini]; grupo = [ini]
            while pilha:
                x, y = pilha.pop()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    n = (x + dx, y + dy)
                    if n in nao_visto:
                        nao_visto.discard(n); pilha.append(n); grupo.append(n)
            aberturas.append(sorted(grupo))

        # escolhe a porta (casa central) de cada abertura; guarda as bordas das
        # portas E suas vizinhas internas â€” assim a casa interna da porta nunca
        # fica isolada do miolo da sala (caso de porta num canto do retÃ¢ngulo).
        portas    = [g[len(g) // 2] for g in aberturas]
        protegido = set()
        for p in portas:
            ex, ey = corr_to_edge[p]
            protegido.add((ex, ey))
            for ddx, ddy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                if room_contains(room, ex + ddx, ey + ddy):
                    protegido.add((ex + ddx, ey + ddy))

        for grupo, porta in zip(aberturas, portas):
            for c in grupo:
                if c == porta:
                    if tiles[c[1]][c[0]] == FLOOR:
                        tiles[c[1]][c[0]] = DOOR
                    if [c[0], c[1]] not in room["doors"]:
                        room["doors"].append([c[0], c[1]])
                else:
                    e = corr_to_edge[c]
                    if e not in protegido:             # nÃ£o isola a entrada de nenhuma porta
                        tiles[e[1]][e[0]] = WALL        # fecha a parede da sala (lado interno)

    return tiles, room_data

def room_contains(room, tx, ty):
    return room["x"] <= tx < room["x"] + room["w"] and room["y"] <= ty < room["y"] + room["h"]

def player_room(rooms, px, py):
    for r in rooms:
        if room_contains(r, px, py):
            return r
    return None

# â”€â”€â”€ GRIMÃ“RIO (SISTEMA DE MAGIAS) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# CatÃ¡logo autoritativo de magias de Pedro (mage) e Lewis (cleric). Esta Ã© a
# camada de DADOS da fundaÃ§Ã£o do sistema de magias; o dispatcher e o roteamento
# ficam em GameRoom (handle_magia / _executar_magia_grimorio).
#
# AdaptaÃ§Ã£o ao modelo de dados do servidor (â‰  spec original):
#   â€¢ atributos do caster sÃ£o scores brutos (int_) â€” bÃ´nus via mod(p["int_"])
#   â€¢ self.monsters Ã© dict (itera .values()); posiÃ§Ãµes sÃ£o pos:[x,y] (nÃ£o tx/ty)
#   â€¢ saves via _testar_save (tupla); INT, fome/sede 0â€“10, log via gm_say
#   â€¢ custo = SLOT do cÃ­rculo (Pedro/Lewis nÃ£o usam MP) + ðŸ–/ðŸ’§ da aÃ§Ã£o
#   â€¢ zonas (escuridÃ£o/silÃªncio) vivem em self.zonas_especiais e ticam por rodada
#
# FUNDAÃ‡ÃƒO: por ora apenas o sistema de escuridÃ£o/visÃ£o estÃ¡ conjurÃ¡vel
# (GRIMORIO_IMPLEMENTADAS). As demais magias entram nos prÃ³ximos prompts.

