def _canonical_monster_ability_id(ability_id):
    return MONSTER_ABILITY_ALIASES.get(str(ability_id or ""), str(ability_id or ""))

def _base_ability_library():
    """Habilidades selecionáveis no editor, por id (a definição é autoritativa).

    Além das técnicas já usadas por monstros, o editor pode reutilizar todas as
    habilidades não mágicas dos heróis e da Guilda. IDs recebem um prefixo de
    origem para não colidirem com habilidades nativas de monstros.
    """
    out = {
        "amaldicoar_monstro": {
            "id": "amaldicoar_monstro", "source": "monstro", "name": "Amaldiçoar",
            "icon": "☠️", "action_type": "acao", "range": 4,
            "save": "vontade", "dc": 13, "curse_mode": "aleatoria",
            "curse_category": "leve",
            "descricao": "Amaldiçoa um alvo: configure a maldição específica ou uma aleatória por gravidade.",
        },
        "causar_sangramento": {
            "id": "causar_sangramento", "source": "monstro", "name": "Causar Sangramento",
            "icon": "🩸", "action_type": "passiva",
            "descricao": "Ataques que acertam aplicam Sangramento; acertos críticos também aplicam Hemorragia.",
        },
        "causar_hemorragia": {
            "id": "causar_hemorragia", "source": "monstro", "name": "Causar Hemorragia",
            "icon": "🩸", "action_type": "passiva", "attack_index": 0,
            "cooldown_turns": 4,
            "descricao": "O ataque selecionado aplica Hemorragia ao acertar e entra em recarga.",
        },
    }
    for monster in MONSTER_DEFS:
        for ability in monster.get("special_abilities", []):
            if ability.get("id"):
                item = deepcopy(ability)
                item.setdefault("source", "monstro")
                out.setdefault(item["id"], item)
    for cls_id, cls in CLASSES.items():
        for skill in cls.get("skills", []):
            if not skill.get("id") or skill.get("id") in GRIMORIO or skill.get("mp") is not None:
                continue  # magias pertencem exclusivamente Ã  aba Magias
            item = {
                "id": f"hero_{cls_id}_{skill['id']}", "source": "heroi",
                "source_id": skill["id"], "source_class": cls_id,
                "name": skill.get("name", skill["id"].replace("_", " ").title()),
                "icon": skill.get("icon", "✦"),
                "descricao": skill.get("description", skill.get("desc", "")),
                "action_type": "passiva" if skill.get("tipo") == "passiva" else "acao",
                # A IA converte habilidades ativas em uma abertura ofensiva que
                # favorece o prÃ³ximo ataque; passivas dÃ£o bÃ´nus permanente leve.
                "monster_effect": "passiva_combate" if skill.get("tipo") == "passiva" else "vantagem_combate",
            }
            if (skill.get("fome_manutencao") or skill.get("sede_manutencao")
                    or (cls_id, skill["id"]) in MONSTER_MAINTENANCE_HERO_SKILLS):
                item["monster_maintenance"] = True
            guild_line = HERO_SKILL_GUILD_LINES.get((cls_id, skill["id"]))
            if guild_line:
                item["guild_progressions"] = [
                    {
                        "id": gid,
                        "level": entry.get("nivel"),
                        "requires": entry.get("requer"),
                        "name": entry.get("nome", gid),
                        "icon": entry.get("icon", "✦"),
                        "description": entry.get("desc", ""),
                    }
                    for gid, entry in GUILD_CATALOG.items()
                    if entry.get("categoria") == "especializacao"
                    and entry.get("classe") == cls_id
                    and entry.get("linha") == guild_line
                    and entry.get("nivel") is not None
                ]
            # A ficha personalizada pode trazer uma cópia antiga da habilidade
            # reutilizada; o catálogo do editor deve manter a definição heroica
            # autoritativa, inclusive suas graduações da Guilda.
            out[item["id"]] = item
    for gid, entry in GUILD_CATALOG.items():
        if not isinstance(entry, dict):
            continue
        if str(gid).startswith("tec_ex_"):
            continue  # metamÃ¡gicas permanecem vinculadas Ã  aba de Magias
        item = {
            "id": f"guild_{gid}", "source": "guilda", "source_id": gid,
            "name": entry.get("nome", gid.replace("_", " ").title()),
            "icon": entry.get("icone", "✦"),
            "descricao": entry.get("desc", entry.get("descricao", "")),
            "action_type": "passiva" if entry.get("categoria") == "especializacao" else "acao",
            "monster_effect": "passiva_combate" if entry.get("categoria") == "especializacao" else "vantagem_combate",
            "guild_category": entry.get("categoria", "habilidade"),
        }
        out.setdefault(item["id"], item)
    # Habilidade configurável do editor: a ficha salva define geometria, dano,
    # teste e como um sucesso afeta o dano. A execução continua no servidor.
    out.setdefault("sopro_dragao", {
        "id": "sopro_dragao", "source": "monstro", "name": "Sopro de Dragão",
        "icon": "🐉", "action_type": "acao", "range": 4,
        "damage": "2d6", "damage_types": [DMG_FIRE], "save": "reflexos", "dc": 13,
        "shape": "linha", "target_mode": "todos", "success_effect": "metade",
        "descricao": "Expele energia em linha ou cone. Configure o elemento, alcance, "
                     "dano, teste de resistência e se o sopro atinge um ou todos os alvos da área.",
    })
    out.setdefault("arremesso_bruto", {
        "id": "arremesso_bruto", "source": "arma", "name": "Arremesso Bruto",
        "icon": "🪓", "action_type": "passiva",
        "descricao": "O arremesso desta arma usa o modificador de Força no acerto e no dano.",
    })
    return out

