async def main():
    # Force UTF-8 on Windows terminals (prevents UnicodeEncodeError with special chars)
    try:
        # line_buffering: sem isto a saida fica presa no buffer quando vai
        # para um cano -- o caso na plataforma de hospedagem. Medido: o log
        # do servidor saia VAZIO; a linha 'escutando em:' so aparecia com -u.
        sys.stdout.reconfigure(encoding='utf-8', errors='replace',
                               line_buffering=True)
    except (AttributeError, TypeError):
        pass
    try:
        sys.stderr.reconfigure(encoding='utf-8', errors='replace')
    except (AttributeError, TypeError):
        pass

    # Rede de seguranca: excecao em task solta so aparece quando o Python coleta
    # a task -- e as nossas ficam referenciadas em self.* , entao nunca eram
    # impressas. Este handler garante que TUDO deixe rastro no console.
    def _falha_nao_tratada(loop, contexto):
        exc = contexto.get("exception")
        print(f"[ERRO NAO TRATADO] {contexto.get('message')}", file=sys.stderr)
        if exc is not None:
            traceback.print_exception(type(exc), exc, exc.__traceback__)
        sys.stderr.flush()
    asyncio.get_running_loop().set_exception_handler(_falha_nao_tratada)

    print("=" * 60)
    print("  LEGENDS FOR HIRE - Servidor (jogo + WebSocket na mesma porta)")
    print("=" * 60)
    print(f"  Local:    http://localhost:{SERVER_PORT}/index.html")
    print()
    print("  Para jogar na internet (link unico para os amigos):")
    print("    1) Deixe este servidor rodando")
    print("    2) Em outro terminal abra um tunel para a porta 8765, ex.:")
    print("         cloudflared tunnel --url http://localhost:8765")
    print("         (ou: ngrok http 8765)")
    print("    3) Compartilhe o link https gerado + /index.html")
    print("  Os amigos so abrem o link, escolhem o nome e entram pelo codigo.")
    print("=" * 60)

    # Rota unica na mesma porta: um unico tunel https cobre pagina + wss, sem
    # mixed content nem endereco digitado a mao.
    #
    # ESCUTAR TAMBEM EM IPv6 e o que torna "localhost" barato no Windows.
    # Escutando so em "0.0.0.0", o nome localhost -- que e o que iniciar.bat
    # abre -- resolve primeiro para ::1, leva recusa, e o navegador so entao
    # cai para 127.0.0.1: ~207 ms perdidos ANTES do primeiro byte.
    # Medido: connect por localhost 207 ms -> 0,7 ms.
    #
    # O paragrafo que ficava aqui sobre "Connection: close" saiu na troca para
    # aiohttp: as conexoes voltaram a ser persistentes, e os ~60 arquivos de
    # uma entrada de masmorra deixaram de abrir uma conexao cada um.
    # Carrega ANTES de aceitar conexao: um jogador que chegasse com o cache
    # vazio veria "conta nao encontrada" e tentaria criar a conta de novo.
    LOJA.carregar()
    print(f"  dados: {sum(len(LOJA.listar(c)) for c in COLECOES)} documentos carregados")

    app = web.Application()
    app.router.add_route("*", "/{cauda:.*}", _rota)
    runner = web.AppRunner(app, access_log=None)
    await runner.setup()

    # Um site por endereco. No Windows sao DOIS (o socket IPv6 nao aceita IPv4
    # por causa do IPV6_V6ONLY, e escutar so em "::" deixaria 127.0.0.1 sem
    # servidor -- os ~207 ms de fallback do nome "localhost" que o
    # tools/test_rede_local.py trava). No Linux e so "::".
    subiu = []
    for host in SERVER_HOSTS:
        try:
            site = web.TCPSite(runner, host, SERVER_PORT)
            await site.start()
            subiu.append(host)
        except OSError as e:
            print(f"  [aviso] nao consegui escutar em {host}: {e}", file=sys.stderr)
    if not subiu:
        print("  [ERRO] nenhum endereco de escuta funcionou. "
              "Tente LFH_HOSTS=0.0.0.0", file=sys.stderr)
        return
    # Deliberado: no spike SP0 o log da plataforma foi a UNICA janela para
    # diagnosticar o bind, e nao havia nada impresso.
    print(f"  escutando em: {', '.join(subiu)}")
    # SIGTERM e como a plataforma (e o pkill) param o servico. SEM isto o
    # finally abaixo nunca roda, e a "saida limpa" nao existe -- medido: a conta
    # criada ficava so na memoria e sumia no encerramento.
    parar = asyncio.Event()
    laco = asyncio.get_running_loop()
    for _sinal in ("SIGTERM", "SIGINT"):
        s = getattr(signal, _sinal, None)
        if s is None:
            continue
        try:
            laco.add_signal_handler(s, parar.set)
        except (NotImplementedError, RuntimeError):
            # Windows nao implementa add_signal_handler no laco; ali o Ctrl+C
            # vira KeyboardInterrupt e o finally cobre.
            pass

    tarefa_descarga = asyncio.create_task(_laco_descarga())
    try:
        await parar.wait()
    finally:
        # Saida limpa: o que estiver sujo vai embora antes de encerrar.
        tarefa_descarga.cancel()
        await _descarregar_loja("encerrando")

if __name__ == "__main__":
    asyncio.run(main())
